const { generatorHandler } = require('@prisma/generator-helper');
const fs = require('fs/promises');
const path = require('path');

const header = [
	'// This file is generated by apps/api/prisma/generators/generate-enums.js during `prisma generate`.',
	'// Do not edit manually: change the enums in apps/api/prisma/enums.prisma instead.',
	'// Plain constants (no @prisma/client import) so the package stays browser-safe for web.',
	'',
].join('\n');

generatorHandler({
	onManifest() {
		return {
			defaultOutput: '../../../packages/dto/src/enums.ts',
			prettyName: 'Shared DTO enum generator',
		};
	},
	async onGenerate(options) {
		const outputFile = options.generator.output;
		if (!outputFile || !outputFile.value) {
			throw new Error('No output file specified for the enums generator');
		}

		const blocks = options.dmmf.datamodel.enums.map((e) => {
			const values = e.values.map(({ name }) => `  ${name}: '${name}',`).join('\n');
			return [
				`export const ${e.name} = {`,
				values,
				'} as const;',
				`export type ${e.name} = (typeof ${e.name})[keyof typeof ${e.name}];`,
			].join('\n');
		});

		const outputPath = path.resolve(outputFile.value);
		await fs.mkdir(path.dirname(outputPath), { recursive: true });
		await fs.writeFile(outputPath, header + '\n' + blocks.join('\n\n') + '\n', 'utf-8');
	},
});
